SELECT 'SCM_ADM_CMBO_SQL_M' AS TBL, '콤보 SQL(공용) — 없을 때만' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'BucketType' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DOM_EXP' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'FCST_TYPE' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'FilterEndCustomerByDivision' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'FilterFromSiteByDivision' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'FilterMyDivision' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'FilterSiteByEndCustomer' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'FilterTeambyDivision' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'MyDivision' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL) S;

/* 5) 클라우드에만 있는 화면 META 행(사내에 없음) — 참고. 지우지 않음 */
SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'DMF0014' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0014_GET_EXCEL_FORM' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_dayRange_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_DELETE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_EXCEL' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_FILTER' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_INSERT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_SORT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_main_UPLOAD' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_spreadTitle_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0014_upload_SAVE' API_ID FROM DUAL) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
